const event = $input.first().json;

const workspaceId = "__SLACK_WORKSPACE_ID__";
const channelId = "__SLACK_REQUESTS_CHANNEL_ID__";

if (
  event.type !== "message" ||
  event.channel !== channelId ||
  (event.team && event.team !== workspaceId)
) {
  return [];
}

if (
  event.bot_id ||
  event.bot_profile ||
  event.hidden ||
  (
    event.subtype &&
    !["thread_broadcast", "file_share"].includes(event.subtype)
  )
) {
  return [];
}

if (
  typeof event.user !== "string" ||
  typeof event.text !== "string" ||
  event.text.trim() === ""
) {
  return [];
}

const messageTs = event.ts;
const threadTs = event.thread_ts || messageTs;
const timestampPattern = /^\d+\.\d{6}$/;

if (
  typeof messageTs !== "string" ||
  typeof threadTs !== "string" ||
  !timestampPattern.test(messageTs) ||
  !timestampPattern.test(threadTs)
) {
  return [];
}

let text = event.text;
const flags = new Set();

const secretPatterns = [
  /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----[\s\S]*?(?:-----END (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|$)/g,
  /\bxox[baprs]-[A-Za-z0-9-]{12,}/g,
  /\bxapp-[A-Za-z0-9-]{12,}/g,
  /\bsk-(?:proj-)?[A-Za-z0-9_-]{16,}/g,
  /\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/g,
  /\bBearer\s+[A-Za-z0-9._~+\/=-]{12,}/gi,
  /\b(?:postgres(?:ql)?|mysql|mongodb(?:\+srv)?|redis|rediss|amqps?):\/\/[^\s/]+:[^\s@]+@[^\s<>"']+/gi,
  /\b(?:password|passwd|api[_-]?key|token|secret)\s*[:=]\s*(?:"[^"]*"|'[^']*'|[^\s,;]+)/gi
];

for (const pattern of secretPatterns) {
  text = text.replace(pattern, () => {
    flags.add("sensitive_data_detected");
    return "[REDACTED_SECRET]";
  });
}

if (/\b(?:production|prod)\b/i.test(text)) {
  flags.add("production_mentioned");
}

if (/\b(?:admin|root|owner|superuser|sudo)\b/i.test(text)) {
  flags.add("privileged_permissions_mentioned");
}

if (
  /ignore.{0,40}(?:instructions|rules)|system\s*prompt|approved\s*[:=]|route\s*[:=]/i.test(text)
) {
  flags.add("instruction_attempt");
}

if (text.length > 12000) {
  flags.add("message_too_long");
  text = text.slice(0, 12000);
}

return [{
  json: {
    text,
    security_flags: [...flags],
    source: "slack",
    workspace_id: workspaceId,
    channel_id: channelId,
    author_id: event.user,
    message_ts: messageTs,
    thread_ts: threadTs,
    event_id: `slack:${workspaceId}:${channelId}:${messageTs}`
  }
}];
